CREATE MATERIALIZED VIEW non_leaf_516 AS
SELECT mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, it2.id AS it2_id, it2.info AS it2_info, ct.id AS ct_id, ct.kind AS ct_kind, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, kt.id AS kt_id, kt.kind AS kt_kind, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, rt.id AS rt_id, rt.role AS rt_role
FROM movie_info AS mi1, info_type AS it2, company_type AS ct, movie_companies AS mc, kind_type AS kt, title AS t, cast_info AS ci, person_info AS pi, name AS n, role_type AS rt
WHERE mi1.movie_id = t.id AND mi1.info ~~* '%e%' AND mi1.info_type_id = 4 AND it2.id = 38 AND ct.id = mc.company_type_id AND mc.movie_id = t.id AND kt.id = t.kind_id AND kt.kind IN ('movie', 'tv mini series', 'tv movie', 'tv series', 'video game', 'video movie') AND t.id = ci.movie_id AND t.production_year <= 2015 AND t.production_year >= 1875 AND ci.role_id = rt.id AND ci.person_id = n.id AND pi.info ~~* '%200%' AND pi.info_type_id = 38 AND n.id = pi.person_id AND rt.role IN ('actor', 'costume designer', 'editor', 'guest', 'miscellaneous crew', 'producer', 'writer');